/**
 * @file 获取cff字符串
 * @author mengke01(kekee000@gmail.com)
 */ 
/**
 * 根据索引获取cff字符串
 *
 * @param  {Object} strings 标准cff字符串索引
 * @param  {number} index   索引号
 * @return {number}         字符串索引
 */ function getCFFString(strings, index) {
    if (index <= 390) {
        index = cff_cffStandardStrings[index];
    } else {
        index = strings[index - 391];
    }
    return index;
}

