            const cmap = ttf.cmap;
            // unicode to index
            Object.keys(cmap).forEach((c)=>{
                if (subset.indexOf(+c) > -1) {
                    const i = cmap[c];
                    subsetMap[i] = true;
                }
            });
            ttf.subsetMap = subsetMap;
