        xml += '<p:tav tm="10000"><p:val><p:strVal val="ppt_y-0.034"/></p:val></p:tav>';
        xml += '<p:tav tm="20000"><p:val><p:strVal val="ppt_y-0.065"/></p:val></p:tav>';
        xml += '<p:tav tm="30000"><p:val><p:strVal val="ppt_y-0.090"/></p:val></p:tav>';
